def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in into s_out."""
    # Simple approach: find first position where they differ
    min_len = min(len(s_in), len(s_out))

    # Find first difference
    pos = -1
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            pos = i
            break

    if pos == -1:
        # One string is prefix of other
        if len(s_in) < len(s_out):
            return ("", s_out[len(s_in):], len(s_in))
        else:
            return (s_in[len(s_out):], "", len(s_out))

    # Look for longest substring match
    old_sub = ""
    new_sub = ""

    # Try to find what's being replaced
    for i in range(pos, len(s_in)):
        if i >= len(s_out):
            break
        if s_in[pos:i+1] in s_out:
            # Check if we can match this substring
            start_pos = s_out.find(s_in[pos:i+1])
            if start_pos + len(s_in[pos:i+1]) <= len(s_out):
                # Check if rest matches
                if s_out[start_pos+len(s_in[pos:i+1]):] == s_in[i+1:]:
                    old_sub = s_in[pos:i+1]
                    new_sub = s_out[start_pos:start_pos+len(s_in[pos:i+1])]
                    break

    # If we couldn't find a clean substring match, try simpler approach
    if not old_sub:
        # For now, just return the first differing character
        if pos < len(s_in) and pos < len(s_out):
            old_sub = s_in[pos]
            new_sub = s_out[pos]
        elif pos < len(s_in):
            old_sub = s_in[pos:]
            new_sub = ""
        else:
            old_sub = ""
            new_sub = s_out[pos:]

    return (old_sub, new_sub, pos)

# Analyze the first changed pair
s_in = 'jghx'
s_out = 'ghijzghhijz'

old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)
print(f"First pair: '{s_in}' -> '{s_out}'")
print(f"Old substring: '{old_sub}', New substring: '{new_sub}', Position: {pos}")

